const std = @import("std");
const ir = @import("compiler").ir;

pub fn check(source: []const u8, program: ir.Program) !void {
    if (std.mem.indexOf(u8, source, "pub fn execute(") == null) return error.MissingExecute;
    if (std.mem.indexOf(u8, source, "while (") == null) return error.MissingReduce;

    var called: usize = 0;
    var buffer: [48]u8 = undefined;

    for (program.functions, 0..) |function, index| {
        if (function.external != null) continue;

        const ordinary = try std.fmt.bufPrint(&buffer, "function_{d}(", .{index});
        const ordinary_calls = std.mem.count(u8, source, ordinary);
        const value = try std.fmt.bufPrint(&buffer, "function_{d}_value(", .{index});
        const value_calls = std.mem.count(u8, source, value);

        if (ordinary_calls > 1 or value_calls > 1) called += 1;
    }

    if (called < 2) return error.MissingReaderCall;
}

const std = @import("std");
const mode = @import("options").mode;
const seed_input = @import("seed.zig");
const program = @import("program");
const Cell = seed_input.Cell;

pub const Case = struct { count: usize, seed: usize = 17, repeat: bool = false, zeros: bool = false, bounded: bool = false };

pub fn isMode(comptime name: []const u8) bool {
    return comptime std.mem.eql(u8, mode, name);
}

pub fn itemAt(args: Case, index: usize) u64 {
    return if (args.zeros) 0 else if (args.repeat) 1 else @intCast((index * 7 + 3) % 11);
}

pub fn fails(args: Case) bool {
    return args.seed == 0 and args.count != 0 and !isMode("optional");
}

pub fn check(result: program.Output, seed: *const seed_input.Seed, args: Case, label: []const u8) !void {
    var values: std.ArrayList(Cell) = .empty;

    defer values.deinit(std.testing.allocator);

    for (seed.values[0..args.seed]) |cell| try values.append(std.testing.allocator, cell);

    var seen: u64 = 0;
    var current_label = label;

    for (0..args.count) |index| {
        const item = itemAt(args, index);
        const selected: usize = if (values.items.len == 0) 0 else @intCast(item % values.items.len);
        const missing = isMode("optional") and (values.items.len == 0 or selected % 2 == 1);
        const old: Cell = if (missing) .{ .value = 0, .label = current_label } else values.items[selected];
        var observed = old.value;

        if (isMode("tuple") or isMode("reference")) observed += values.items.len;
        if (isMode("nested")) observed += values.items.len + old.value + if (selected % 2 == 0) old.value else @as(u64, 0);
        if (isMode("reverse")) std.mem.reverse(Cell, values.items);
        try values.append(std.testing.allocator, .{ .value = old.value + item + 1, .label = old.label });
        if (isMode("concat")) try values.append(std.testing.allocator, .{ .value = old.value + item + 2, .label = current_label });

        seen += observed;
        current_label = old.label;
    }

    try std.testing.expectEqual(values.items.len, result.values.len);
    try std.testing.expectEqualSlices(*const Cell, result.values, result.mirror);
    try std.testing.expectEqual(args.seed, result.original.len);
    for (result.values, values.items) |actual, expected| try std.testing.expectEqualDeep(expected, actual.*);
    for (result.original, seed.pointers[0..args.seed]) |actual, expected| try std.testing.expectEqualDeep(expected.*, actual.*);
    try std.testing.expectEqual(seen, result.seen);
    try std.testing.expectEqualStrings(current_label, result.label);
    try std.testing.expectEqual(@as(u64, @intCast(args.count)), result.count);
}

import read from "./read"

import type { State, StepInput } from "./model"

export type Input = StepInput

export type Output = State

export default function (in: Input): Output {
    const selected = in.state.values.length == 0 ? 0 : in.item % in.state.values.length
    const old = read({ values: in.state.values, selected: selected })

    return { values: in.state.values.push({ value: old.cell.value + in.item + 1, label: old.pair[0] })[0], seen: in.state.seen + old.cell.value + old.length + old.pair[1] + (old.maybe?.value ?? 0), label: old.pair[0], count: in.state.count + 1 }
}

import { resolve } from 'node:path'
import { package_dir, writeCatalog, writeOutput } from './shared/catalog.ts'
import { readRows } from './shared/json.ts'

type Sample = {
    name: 'increment' | 'square' | 'object_key'
    path: string
    sha256: string
    parameter: string
    expression: string
    value: string
    expected: number
}

const samples = readRows<Sample>(resolve(package_dir, 'src/data/arrow_returns.jsonl'))
const base = 'language/expressions/arrow/returns'
const numbers = [-1024, -99, -7, -1, 0, 1, 2, 3, 4, 17, 127, 257, 65535]
const named = new Map([
    [1, 'one'],
    [3, 'three']
])
const values = [
    { name: 'empty', items: [] },
    ...numbers.map(item => ({ name: named.get(item) ?? `value_${item}`, items: [item] })),
    { name: 'signed', items: [-7, 0, 43] },
    { name: 'repeated', items: [1, 1, 1] },
    { name: 'boundary', items: [65535, -65535] },
    { name: 'mixed', items: [-1024, 257, -1, 3] }
]

function expectedValue(name: Sample['name'], item: number): number {
    if (name === 'increment') return item + 1
    if (name === 'square') return item * item

    return item
}

for (const sample of samples) {
    const mapped = `in.items.map(${sample.parameter} => ${sample.expression})`
    const body =
        sample.name === 'object_key'
            ? `    const cells = ${mapped}\n\n    return cells.map(cell => cell.key)`
            : `    return ${mapped}`

    writeOutput(
        `tests/${base}/${sample.name}/cases.zx`,
        `export type Input = { items: i64[] }

export type Output = i64[]

export default function (in: Input): Output {
${body}
}
`
    )
    writeCatalog(
        `tests/${base}/${sample.name}/cases.jsonl`,
        values.map(value => ({
            id: `${base}/${sample.name}/${value.name}`,
            input: { items: value.items },
            expected: { value: value.items.map(item => expectedValue(sample.name, item)) }
        }))
    )
}

writeCatalog(
    'upstream/reviews/language/expressions/arrow_returns.jsonl',
    samples.map(sample => {
        const id = `${base}/${sample.name}/${sample.value}`

        return {
            path: sample.path,
            sha256: sample.sha256,
            status: 'adapted',
            reason: `通过单元素 map 将原 lambda 调用一次，保持原参数、表达式 body 与唯一运行时值断言；${sample.name === 'object_key' ? '记录返回在随后字段投影中读取 key。' : '数值结果按原断言验证。'}var 与一等函数调用宿主改为 ZX inline callback，因此属于适配，未声称原 JavaScript 文件直接运行于 zxc。`,
            contract: 'packages/compiler/src/zx/analysis/transforms.zig',
            cases: [id],
            assertions: [{ case: id, field: 'value', expected: [sample.expected] }]
        }
    })
)
